"""Identify a tokenizer by exact calibration encoding, then decode the payload.

Single-file submission: main.py (generated by build_submission.py).
Default contract: ./test-input.json -> ./test-output.json.
The bundled tiktoken tables work without third-party packages or network access.
HF/SentencePiece fallbacks require their libraries and local or public vocabularies.
"""

import argparse
import base64
from functools import lru_cache
import json
from pathlib import Path
import re
import struct
import sys
import urllib.request
import zlib


HF_MODELS = (
    "bert-base-uncased", "bert-base-cased", "bert-base-multilingual-cased",
    "bert-base-multilingual-uncased", "distilbert-base-uncased",
    "roberta-base", "xlm-roberta-base", "t5-small", "albert-base-v2",
    "xlnet-base-cased", "EleutherAI/gpt-neox-20b", "facebook/opt-125m",
    "facebook/bart-base", "microsoft/deberta-base", "microsoft/deberta-v3-base",
    "TinyLlama/TinyLlama-1.1B-Chat-v1.0", "openlm-research/open_llama_3b",
    "mistralai/Mistral-7B-v0.1", "hf-internal-testing/llama-tokenizer",
    "Qwen/Qwen2.5-0.5B", "google/byt5-small", "google/mt5-small",
)


@lru_cache(maxsize=3)
def vocabulary(table_name):
    packed = memoryview(zlib.decompress(base64.b85decode(BUNDLED_TABLES[table_name])))
    decoder = {}
    pos = 0
    token_id = 0
    while pos < len(packed):
        length = struct.unpack_from("<H", packed, pos)[0]
        pos += 2
        if length:
            decoder[token_id] = bytes(packed[pos:pos + length])
        pos += length
        token_id += 1
    return decoder


@lru_cache(maxsize=8)
def unicode_pattern(source):
    """Translate Unicode property escapes into bundled, exact character ranges."""
    parts = []
    inside = False
    pos = 0
    while pos < len(source):
        if source[pos:pos + 3] == "\\p{":
            end = source.index("}", pos)
            ranges = UNICODE_RANGES[source[pos + 3:end]]
            parts.append(ranges if inside else "[" + ranges + "]")
            pos = end + 1
            continue
        if source[pos:pos + 2] in (r"\s", r"\S"):
            ranges = UNICODE_RANGES["space"]
            if inside:
                parts.append(ranges)
            else:
                parts.append("[" + ("^" if source[pos + 1] == "S" else "") + ranges + "]")
            pos += 2
            continue
        char = source[pos]
        if char == "\\" and pos + 1 < len(source):
            parts.append(source[pos:pos + 2])
            pos += 2
            continue
        if char == "[":
            inside = True
        elif char == "]":
            inside = False
        parts.append(char)
        pos += 1
    expression = "".join(parts)
    # Possessive quantifiers in upstream's optimized patterns need Python 3.11.
    # The equivalent unoptimized greedy forms also support older interpreters.
    if sys.version_info < (3, 11):
        expression = re.sub(r"([+*?]|\{\d+(?:,\d*)?\})\+", r"\1", expression)
    return re.compile(expression)


class BundledTokenizer:
    def __init__(self, name):
        self.name = name
        config = BUNDLED_CONFIGS[name]
        self.decoder = vocabulary(config["table"])
        if "limit" in config:
            self.decoder = {k: v for k, v in self.decoder.items() if k < config["limit"]}
        self.special = config["special"]
        self.pattern = unicode_pattern(config["pattern"])
        self.ranks = None

    def decode(self, ids):
        special_ids = {v: k.encode("utf-8") for k, v in self.special.items()}
        return b"".join(self.decoder[i] if i in self.decoder else special_ids[i]
                        for i in ids).decode("utf-8", errors="replace")

    def _bpe(self, word):
        direct = self.ranks.get(word)
        if direct is not None:
            return [direct]
        pieces = [bytes([b]) for b in word]
        while len(pieces) > 1:
            best_rank = None
            best_pos = None
            for pos in range(len(pieces) - 1):
                rank = self.ranks.get(pieces[pos] + pieces[pos + 1])
                if rank is not None and (best_rank is None or rank < best_rank):
                    best_rank, best_pos = rank, pos
            if best_pos is None:
                break
            pieces[best_pos:best_pos + 2] = [pieces[best_pos] + pieces[best_pos + 1]]
        return [self.ranks[piece] for piece in pieces]

    def encode(self, text, special=False):
        if self.ranks is None:
            self.ranks = {value: key for key, value in self.decoder.items()}
        if special and self.special:
            parts = re.split("(" + "|".join(re.escape(s) for s in
                             sorted(self.special, key=len, reverse=True)) + ")", text)
        else:
            parts = [text]
        result = []
        for part in parts:
            if special and part in self.special:
                result.append(self.special[part])
            else:
                for match in self.pattern.finditer(part):
                    result.extend(self._bpe(match.group().encode("utf-8")))
        return result


def check_input(data):
    text = data["calibration"]["text"]
    if not isinstance(text, str):
        raise ValueError("calibration.text must be a string")
    for section in ("calibration", "challenge"):
        ids = data[section]["token_ids"]
        if not isinstance(ids, list) or any(type(i) is not int or i < 0 for i in ids):
            raise ValueError(section + ".token_ids must be a list of nonnegative integers")
    if not data["calibration"]["token_ids"]:
        raise ValueError("Empty calibration cannot identify a tokenizer")


def bundled_solution(data):
    text = data["calibration"]["text"]
    ids = data["calibration"]["token_ids"]
    challenge = data["challenge"]["token_ids"]
    # Prefer canonical base names when variants have identical observable behavior.
    for name in ("cl100k_base", "o200k_base", "p50k_base", "r50k_base",
                 "p50k_edit", "o200k_harmony"):
        tokenizer = BundledTokenizer(name)
        try:
            if tokenizer.decode(ids) != text:
                continue
            if tokenizer.encode(text) != ids and tokenizer.encode(text, special=True) != ids:
                continue
            message = tokenizer.decode(challenge)
        except (KeyError, UnicodeError):
            continue
        return {"tokenizer_id": name, "decoded_message": message}
    return None


def public_file(model_id, filename):
    """Fetch a fixed public tokenizer resource; never send input text to a service."""
    from urllib.parse import quote
    url = "https://huggingface.co/" + quote(model_id, safe="/") + "/resolve/main/" + filename
    request = urllib.request.Request(url, headers={"User-Agent": "tokenizer-calibration/1.0"})
    with urllib.request.urlopen(request, timeout=5) as response:
        return response.read(32 * 1024 * 1024)


def local_candidates(directory):
    # Explicitly local tokenizer assets only; no remote Python code is executed.
    roots = [directory, directory / "tokenizers", Path.home() / ".cache/huggingface/hub"]
    for root in dict.fromkeys(roots):
        if not root.is_dir():
            continue
        for filename in ("tokenizer.json", "tokenizer.model", "spiece.model", "sentencepiece.bpe.model"):
            paths = root.rglob(filename) if root != directory else root.glob(filename)
            for path in paths:
                name = path.parent.name
                for parent in path.parents:
                    if parent.name.startswith("models--"):
                        name = parent.name[len("models--"):].replace("--", "/")
                        break
                yield name, path


def try_fast_tokenizer(name, tokenizer, data):
    text = data["calibration"]["text"]
    ids = data["calibration"]["token_ids"]
    for add_special in (False, True):
        if tokenizer.encode(text, add_special_tokens=add_special).ids != ids:
            continue
        # Determine whether decoding should preserve special tokens using the
        # calibration itself. Never clean up spaces in the decoded challenge.
        keep_special = tokenizer.decode(ids, skip_special_tokens=False) == text
        message = tokenizer.decode(data["challenge"]["token_ids"],
                                   skip_special_tokens=not keep_special)
        return {"tokenizer_id": name, "decoded_message": message}
    return None


def try_sentencepiece(name, processor, data):
    text = data["calibration"]["text"]
    ids = data["calibration"]["token_ids"]
    for bos, eos in ((False, False), (True, False), (False, True), (True, True)):
        if (bos and processor.bos_id() < 0) or (eos and processor.eos_id() < 0):
            continue
        if processor.encode(text, out_type=int, add_bos=bos, add_eos=eos) == ids:
            payload = data["challenge"]["token_ids"]
            if any(i >= processor.get_piece_size() for i in payload):
                return None
            return {"tokenizer_id": name, "decoded_message": processor.decode(payload)}
    return None


def other_solution(data, directory, online=True):
    try:
        from tokenizers import Tokenizer
    except ImportError:
        Tokenizer = None
    try:
        import sentencepiece as spm
    except ImportError:
        spm = None
    for name, path in local_candidates(directory):
        try:
            if path.suffix == ".json" and Tokenizer is not None:
                result = try_fast_tokenizer(name, Tokenizer.from_file(str(path)), data)
            elif path.suffix == ".model" and spm is not None:
                result = try_sentencepiece(name, spm.SentencePieceProcessor(model_file=str(path)), data)
            else:
                continue
            if result:
                return result
        except Exception:
            continue
    if not online or (Tokenizer is None and spm is None):
        return None

    # Downloads are bounded and concurrent to avoid serial network timeouts.
    from concurrent.futures import ThreadPoolExecutor

    def probe(name):
        if Tokenizer is not None:
            try:
                raw = public_file(name, "tokenizer.json")
                result = try_fast_tokenizer(name, Tokenizer.from_str(raw.decode("utf-8")), data)
                if result:
                    return result
            except Exception:
                pass
        if spm is not None and any(key in name.lower() for key in ("t5", "albert", "xlnet", "llama", "mistral")):
            for filename in ("spiece.model", "tokenizer.model"):
                try:
                    raw = public_file(name, filename)
                    result = try_sentencepiece(name, spm.SentencePieceProcessor(model_proto=raw), data)
                    if result:
                        return result
                except Exception:
                    continue
        return None

    with ThreadPoolExecutor(max_workers=8) as pool:
        # Keep deterministic model priority even when downloads finish out of order.
        results = pool.map(probe, HF_MODELS)
        for result in results:
            if result:
                return result
    return None


def solve(data, directory=None, online=True):
    check_input(data)
    result = bundled_solution(data)
    if result is None:
        result = other_solution(data, Path(directory or Path.cwd()), online=online)
    if result is None:
        raise ValueError("No candidate exactly reproduces calibration.token_ids. "
                         "For HF/SentencePiece, provide tokenizer assets and their libraries.")
    return result


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("input", nargs="?", help="Input JSON; default test-input.json")
    parser.add_argument("output", nargs="?", help="Output JSON; default test-output.json")
    parser.add_argument("-o", "--output", dest="output_option")
    parser.add_argument("--offline", action="store_true", help="Disable public tokenizer downloads")
    args = parser.parse_args()
    input_path = Path(args.input or "test-input.json")
    if args.input is None and not input_path.exists() and Path("train-input.json").exists():
        input_path = Path("train-input.json")
    output_path = args.output_option or args.output or "test-output.json"
    if str(input_path) == "-":
        data = json.loads(sys.stdin.read().lstrip("\ufeff"))
        directory = Path.cwd()
    else:
        with input_path.open(encoding="utf-8-sig") as stream:
            data = json.load(stream)
        directory = input_path.resolve().parent
    result = solve(data, directory, online=not args.offline)
    if output_path == "-":
        json.dump(result, sys.stdout, ensure_ascii=False)
        sys.stdout.write("\n")
    else:
        with open(output_path, "w", encoding="utf-8", newline="\n") as stream:
            json.dump(result, stream, ensure_ascii=False, indent=2)
            stream.write("\n")


